(()=>{'use strict';const A=[...document.querySelectorAll('.exercise')],B=document.querySelector('#progressBar'),K='andalusi-v2',w=(m,e)=>console.warn('[andalusi] '+m,e||''),get=()=>{try{return JSON.parse(localStorage.getItem(K)||'{}')}catch(e){w('storage',e);return{}}},save=()=>{try{localStorage.setItem(K,JSON.stringify(Object.fromEntries(A.map(x=>[x.id,{v:x.querySelector('textarea')?.value||'',d:!!x.querySelector('[data-check]')?.checked}]))))}catch(e){w('storage',e)}},draw=()=>{let n=A.filter(x=>x.querySelector('[data-check]')?.checked).length,p=A.length?Math.round(100*n/A.length):0;if(B)B.style.width=p+'%',B.textContent=p+'%',B.setAttribute('aria-valuenow',p)};let d=get();A.forEach(x=>{let o=d[x.id]||{},t=x.querySelector('textarea'),c=x.querySelector('[data-check]');if(t)t.value=o.v||'';if(c)c.checked=!!o.d});document.addEventListener('input',e=>{if(e.target.matches('textarea'))save()});document.addEventListener('change',e=>{if(e.target.matches('[data-check]'))save(),draw()});document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action;if(a==='print')print();else if(a==='reset'){try{localStorage.removeItem(K)}catch(e){w('storage',e)}location.reload()}else if(a==='download'){let u=URL.createObjectURL(new Blob([JSON.stringify(get(),null,2)],{type:'application/json'})),x=document.createElement('a');x.href=u;x.download='progreso-musica-andalusi-flamenco.json';x.click();setTimeout(()=>URL.revokeObjectURL(u),0)}});addEventListener('error',e=>w('error',e.error||e.message));addEventListener('unhandledrejection',e=>w('rejection',e.reason));draw();if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./andalusi-sw.js').catch(e=>w('cache',e)),{once:true})})();